fn reverse(a: &Vec<char>) -> Vec<char> {
    let n = a.len();
    let mut result = Vec::with_capacity(n);
    // Iterate from the last index down to 0
    for i in (0..n).rev() {
        result.push(a[i]);
    }
    result
}

